from dataclasses import dataclass, field
from typing import List, Optional, Dict, Any

@dataclass
class ImagePayload:
    image_bytes: bytes

@dataclass
class LabelAnnotation:
    description: str
    score: float

@dataclass
class DetectedLabels:
    labels: List[LabelAnnotation] = field(default_factory=list)

@dataclass
class TextAnnotation:
    text: str
    bounds: List[Dict[str, Any]] # Vertices for bounding box

@dataclass
class DetectedText:
    texts: List[TextAnnotation] = field(default_factory=list)

@dataclass
class SafeSearchAnnotation:
    adult: str
    spoof: str
    medical: str
    violence: str
    racy: str

@dataclass
class ImageModerationResult:
    safe_search_annotation: Optional[SafeSearchAnnotation] = None

@dataclass
class ImageDescription:
    description: str
    confidence: float

from google.cloud import vision
import os

class VisionClient:
    def __init__(self):
        # Google Cloud Vision API client is implicitly authenticated via GOOGLE_APPLICATION_CREDENTIALS
        # or by running in a Google Cloud environment.
        self._client = vision.ImageAnnotatorClient()

    def get_image_annotator_client(self):
        return self._client

from google.cloud import vision
from vision_models import ImagePayload, DetectedText, TextAnnotation
from vision_client import VisionClient

def detect_image_text(payload: ImagePayload, config: dict = None) -> DetectedText:
    config = config or {}
    client = VisionClient().get_image_annotator_client()

    image = vision.Image(content=payload.image_bytes)
    response = client.text_detection(image=image)

    if response.error.message:
        raise RuntimeError(response.error.message)

    texts = []
    if response.text_annotations:
        # The first annotation is the full text detected in the image
        full_text_annotation = response.text_annotations[0]
        # Other annotations are individual words or lines
        for text_annotation in response.text_annotations[1:]:
            texts.append(TextAnnotation(
                text=text_annotation.description,
                bounds=[{'x': v.x, 'y': v.y} for v in text_annotation.bounding_poly.vertices]
            ))

    return DetectedText(texts=texts)

from google.cloud import vision
from vision_models import ImagePayload, ImageModerationResult, SafeSearchAnnotation
from vision_client import VisionClient

def score_image_safety(payload: ImagePayload, config: dict = None) -> ImageModerationResult:
    config = config or {}
    client = VisionClient().get_image_annotator_client()

    image = vision.Image(content=payload.image_bytes)
    response = client.safe_search_detection(image=image)

    if response.error.message:
        raise RuntimeError(response.error.message)

    safe_search = response.safe_search_annotation

    return ImageModerationResult(
        safe_search_annotation=SafeSearchAnnotation(
            adult=vision.Likelihood(safe_search.adult).name,
            spoof=vision.Likelihood(safe_search.spoof).name,
            medical=vision.Likelihood(safe_search.medical).name,
            violence=vision.Likelihood(safe_search.violence).name,
            racy=vision.Likelihood(safe_search.racy).name,
        )
    )

import google.generativeai as genai
import os
from vision_models import DetectedLabels, ImageDescription, DetectedText, ImageModerationResult

def image_summary(analysis_results: dict, config: dict = None) -> dict:
    config = config or {}

    # Configure the API key for Google Generative AI
    # It's recommended to set GOOGLE_API_KEY as an environment variable
    genai.configure(api_key=os.environ.get("GOOGLE_API_KEY"))
    model = genai.GenerativeModel('gemini-pro')

    # Extract relevant information from analysis_results
    labels = analysis_results.get("labels", DetectedLabels()).labels
    description = analysis_results.get("description", ImageDescription(description="", confidence=0.0)).description
    detected_text = analysis_results.get("detected_text", DetectedText()).texts
    safety_scores = analysis_results.get("safety_scores", ImageModerationResult()).safe_search_annotation

    prompt = """
    Summarize the following image analysis results in a concise paragraph. 
    Focus on key visual elements, detected text, and any safety concerns. 

    Labels: {}
    Description: {}
    Detected Text: {}
    Safety Scores: {}
    """.format(
        ", ".join([f"{label.description} (confidence: {label.score:.2f})" for label in labels]),
        description,
        ", ".join([text.text for text in detected_text]),
        f"Adult: {safety_scores.adult}, Spoof: {safety_scores.spoof}, Medical: {safety_scores.medical}, Violence: {safety_scores.violence}, Racy: {safety_scores.racy}" if safety_scores else "N/A"
    )

    try:
        response = model.generate_content(prompt)
        return {"summary": response.text}
    except Exception as e:
        raise RuntimeError(f"Error generating summary: {e}")

from google.cloud import translate_v3 as translate
import os

def alt_text_translate(text: str, target_language_code: str, config: dict = None) -> dict:
    config = config or {}

    project_id = os.environ.get("GOOGLE_CLOUD_PROJECT_ID")
    if not project_id:
        raise ValueError("GOOGLE_CLOUD_PROJECT_ID environment variable not set.")

    client = translate.TranslationServiceClient()

    parent = f"projects/{project_id}/locations/global"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [text],
            "target_language_code": target_language_code,
        }
    )

    translated_text = response.translations[0].translated_text if response.translations else text

    return {"translated_text": translated_text}

import google.generativeai as genai
import os

def visual_safety_text(text_content: str, config: dict = None) -> dict:
    config = config or {}

    genai.configure(api_key=os.environ.get("GOOGLE_API_KEY"))
    model = genai.GenerativeModel('gemini-pro')

    prompt = f"""
    Analyze the following text for any unsafe content, including but not limited to: 
    hate speech, sexual content, violent content, or harassment. 
    Provide a safety rating or a brief statement about the safety of the text.

    Text: """{text_content}"""
    """

    try:
        response = model.generate_content(prompt, safety_settings={
            'HARM_CATEGORY_HARASSMENT': 'BLOCK_NONE',
            'HARM_CATEGORY_HATE_SPEECH': 'BLOCK_NONE',
            'HARM_CATEGORY_SEXUALLY_EXPLICIT': 'BLOCK_NONE',
            'HARM_CATEGORY_DANGEROUS_CONTENT': 'BLOCK_NONE',
        })

        # Access safety ratings from the response
        safety_ratings = {f"_safety_{rating.category.name.lower().replace('harm_category_', '')}": rating.probability.name for rating in response.candidates[0].safety_ratings}

        return {"safety_analysis": response.text, **safety_ratings}
    except Exception as e:
        # If the content is blocked, an exception will be raised. Handle it.
        return {"safety_analysis": f"Content analysis blocked: {e}", "blocked": True}
